476	function runEvalCommand(options: EvalOptions) {
477	  assertFileExists(options.outputs);
478	  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
479	    outputsPath: options.outputs,
480	    referencesPath: options.references
481	  });
482	  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
483	    outputs: dataset.outputs,
484	    references: dataset.references
485	  });
486	  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
487	    evaluations,
488	    outputsPath: dataset.outputsPath,
489	    referencesPath: dataset.referencesPath
490	  });
491	  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
492	    report,
493	    format: options.format ?? 'json',
494	    reportPath: options.report
495	  });
496	  log.success('Evaluation report generated.', { path: resolvedPath });
497	}
