      expect(exact.passed).toBe(true);
      expect(tox.passed).toBe(true);
    });

    it('fails threshold when score is below minimum', () => {
      const evaluations = runEvaluations({
        outputs: ['Hello'],
        references: ['hello']
      });
      const report = generateReport({
        evaluations,
        outputsPath: '/tmp/outputs.json',
        referencesPath: '/tmp/refs.json',
        thresholds: { exact_match: 0.95 },
        generatedAt: '2024-01-01T00:00:00.000Z'
      });
      expect(report.passed).toBe(false);
      const exact = report.thresholds.find((t) => t.metric === 'exact_match');
      expect(exact.passed).toBe(false);
      expect(exact.score).toBe(1);
      expect(exact.min).toBe(0.95);
    });

    it('fails threshold when metric has no score', () => {
      const evaluations = runEvaluations({
        outputs: ['Hello'],
        references: []
      });
      const report = generateReport({
        evaluations,
        outputsPath: '/tmp/outputs.json',
        referencesPath: '/tmp/refs.json',
        thresholds: { exact_match: 0.5 },
        generatedAt: '2024-01-01T00:00:00.000Z'
      });
      expect(report.passed).toBe(false);
      const exact = report.thresholds.find((t) => t.metric === 'exact_match');
      expect(exact.passed).toBe(false);
      expect(exact.score).toBeNull();
    });

    it('records all threshold results in JSON report', () => {
      const evaluations = runEvaluations({
        outputs: ['Hello'],
        references: ['hello']
      });
      const report = generateReport({
        evaluations,
        outputsPath: '/tmp/outputs.json',
        referencesPath: '/tmp/refs.json',
        thresholds: { exact_match: 0.8, toxicity: 0.9 },
        generatedAt: '2024-01-01T00:00:00.000Z'
      });

      const dir = createTempDir();
      const jsonPath = writeReport({
        report,
        format: 'json',
        reportPath: path.join(dir, 'report.json')
      });

      const content = fs.readFileSync(jsonPath, 'utf8');
      const parsed = JSON.parse(content);
      expect(parsed.passed).toBe(true);
      expect(parsed.thresholds).toHaveLength(2);
    });

    it('includes thresholds section in markdown report', () => {
      const evaluations = runEvaluations({
        outputs: ['Hello'],
        references: ['hello']
      });
      const report = generateReport({
        evaluations,
        outputsPath: '/tmp/outputs.json',
        referencesPath: '/tmp/refs.json',
        thresholds: { exact_match: 0.8, toxicity: 0.9 },
        generatedAt: '2024-01-01T00:00:00.000Z'
      });

      const dir = createTempDir();
      const markdownPath = writeReport({
        report,
        format: 'markdown',
        reportPath: path.join(dir, 'report.md')
      });

      const content = fs.readFileSync(markdownPath, 'utf8');
      expect(content).toContain('## Thresholds');
      expect(content).toContain('PASS');
    });

    it('shows FAIL for failed thresholds in markdown report', () => {
      const evaluations = runEvaluations({
        outputs: ['Hello'],
        references: ['hello']
      });
      const report = generateReport({
        evaluations,
        outputsPath: '/tmp/outputs.json',
        referencesPath: '/tmp/refs.json',
        thresholds: { exact_match: 0.95 },
        generatedAt: '2024-01-01T00:00:00.000Z'
      });

      const dir = createTempDir();
      const markdownPath = writeReport({
        report,
        format: 'markdown',
        reportPath: path.join(dir, 'report.md')
      });

      const content = fs.readFileSync(markdownPath, 'utf8');
      expect(content).toContain('## Thresholds');
      expect(content).toContain('FAIL');
    });

    it('handles multiple thresholds with mixed pass/fail', () => {
      const evaluations = runEvaluations({
        outputs: ['Hello', 'kill you'],
        references: ['hello', 'greet you']
      });
      const report = generateReport({
        evaluations,
        outputsPath: '/tmp/outputs.json',
        referencesPath: '/tmp/refs.json',
        thresholds: { exact_match: 0.5, toxicity: 0.95 },
        generatedAt: '2024-01-01T00:00:00.000Z'
      });
      expect(report.passed).toBe(false);
      expect(report.thresholds).toHaveLength(2);
      const exact = report.thresholds.find((t) => t.metric === 'exact_match');
      const tox = report.thresholds.find((t) => t.metric === 'toxicity');
      expect(exact.passed).toBe(true);
      expect(tox.passed).toBe(false);
    });

    it('preserves existing behavior without thresholds', () => {
      const evaluations = runEvaluations({
        outputs: ['Hello'],
        references: ['hello']
      });
      const report = generateReport({
        evaluations,
        outputsPath: '/tmp/outputs.json',
        referencesPath: '/tmp/refs.json',
        generatedAt: '2024-01-01T00:00:00.000Z'
      });
      expect(report).toHaveProperty('metadata');
      expect(report).toHaveProperty('metrics');
      expect(report.passed).toBeUndefined();
      expect(report.thresholds).toBeUndefined();
    });
  });
});

