  if (report.thresholds && report.thresholds.length > 0) {
    lines.push('## Thresholds');
    lines.push('');
    report.thresholds.forEach((threshold) => {
      const status = threshold.passed ? 'PASS' : 'FAIL';
      lines.push(`- **${threshold.metric}:** ${status}`);
      lines.push(`  - Minimum: ${threshold.min}`);
      lines.push(`  - Score: ${threshold.score ?? 'n/a'}`);
    });
    lines.push('');
  }
  lines.push('---');
  lines.push('*Generated by FRAI Evaluation Harness*');
  return lines.join('\n');
}

export function resolveReportPath(reportPath, format = 'json') {
  if (!reportPath) {
    return format === 'markdown' ? path.resolve('frai-eval-report.md') : path.resolve('frai-eval-report.json');
  }
